const $=s=>document.querySelector(s),escape=MailLogic.escape;
let account='',provider='icloud',mails=[],folder='quiet',filter='all',quietFilter='reply',current=null,draftId=null,replyTo=null,sending=false,syncing=false,session=null,radarFilter='all',undoAction=null,ready=false,storageHealthy=true;
const native=!!window.webkit?.messageHandlers?.mail;const requests=new Map();let pendingWrites=Promise.resolve(true);ready=!native;
function bridge(action,fields={}){return new Promise((resolve,reject)=>{if(!native){reject(new Error('Open the Mac app to use this feature.'));return}const id=crypto.randomUUID();const timer=setTimeout(()=>{requests.delete(id);reject(new Error('The operation is taking too long. Check the account window before retrying.'))},300000);requests.set(id,{resolve,reject,timer});window.webkit.messageHandlers.mail.postMessage({action,id,...fields})})}
window.nativeResponse=payload=>{const req=requests.get(payload.id);if(!req){if(payload.id==='menu'){if(payload.ok)applySync(payload.data);else toast(payload.error)}return}clearTimeout(req.timer);requests.delete(payload.id);payload.ok?req.resolve(payload.data):req.reject(new Error(payload.error))};
function storageKey(){return account?'stupid-mail-icloud-v2:'+account:'stupid-mail-v1'}
function load(){try{const saved=JSON.parse(localStorage.getItem(storageKey()));mails=Array.isArray(saved)?saved:account?[]:structuredClone(seed)}catch{mails=account?[]:structuredClone(seed)}current=null;session=null;undoAction=null;window.dispatchEvent(new Event('mail-account-changed'))}
async function loadNativeCache(){
 if(!native)return;
 try{const result=await bridge('readCache',{account});if(Array.isArray(result.messages))mails=result.messages;storageHealthy=true;}
 catch(error){storageHealthy=false;showStatus(error.message,true);throw error}
}
function save(){
 if(!storageHealthy){toast('Local mailbox storage is unavailable. Reopen the app before making changes.');return Promise.resolve(false)}
 const contents=JSON.stringify(mails),savedAccount=account;
 if(native){pendingWrites=pendingWrites.then(()=>bridge('writeCache',{account:savedAccount,contents})).then(()=>true).catch(error=>{showStatus(error.message,true);toast(error.message);return false});return pendingWrites}
 try{localStorage.setItem(storageKey(),contents);pendingWrites=Promise.resolve(true);return pendingWrites}catch{toast('This device could not save changes. Keep the app open and free some disk space.');pendingWrites=Promise.resolve(false);return pendingWrites}
}
function rememberChange(message){undoAction={account,id:message.id,before:structuredClone(message)};$('#undo-change').hidden=false}
function undoChange(){if(!undoAction||undoAction.account!==account)return;const index=mails.findIndex(m=>m.id===undoAction.id);if(index>=0){mails[index]=undoAction.before;if(current?.id===undoAction.id)current=mails[index];session?.handled.delete(undoAction.id);save();render();toast('Last change undone.')}undoAction=null;$('#undo-change').hidden=true}
function toast(text){$('#toast').textContent=text;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',6500)}
function showStatus(text,error=false){$('#connection-status').textContent=text;$('#connection-status').classList.toggle('error',error)}
const providerTitle=()=>({icloud:'iCloud',gmail:'Gmail',outlook:'Outlook',yahoo:'Yahoo',aol:'AOL',fastmail:'Fastmail',zoho:'Zoho',gmx:'GMX',proton:'Proton Mail',custom:'Mail'}[provider]||'Mail');
const folders=[['quiet','◉','Quiet Inbox'],['inbox','▣','All mail'],['waiting','◷','Follow-up Radar'],['snoozed','☾','Snoozed'],['starred','☆','Starred'],['sent','↗','Sent here'],['drafts','▤','Drafts'],['archive','▧','Put away'],['trash','♧','Hidden']];
const folderMail=key=>mails.filter(m=>key==='quiet'?m.folder==='inbox'&&!MailLogic.snoozed(m):key==='snoozed'?MailLogic.snoozed(m)&&m.folder==='inbox':key==='waiting'?m.followUp:key==='starred'?m.star&&m.folder!=='trash':m.folder===key);
function dateText(value){const d=new Date(value);return isNaN(d)?value:d.toLocaleDateString(undefined,{month:'short',day:'numeric'})}
function render(){
 $('#setup-note').hidden=Boolean(account)||folder!=='quiet';$('#start-connect').disabled=!ready||syncing;
 $('#folders').innerHTML=folders.map(([key,icon,title])=>`<button data-folder="${key}" title="${title}" aria-label="${title}" class="${folder===key?'active':''}"><span class="icon">${icon}</span><span class="folder-label">${title}</span><span class="count">${folderMail(key).length||''}</span></button>`).join('');
 $('#folder-title').textContent=folders.find(f=>f[0]===folder)[2];
 const subtitles={quiet:'A little attention. A few decisions. Then go live your life.',inbox:account?'Your latest inbox messages and locally saved items.':'Your demo inbox. Make yourself at home.',waiting:'A gentle nudge, without keeping it all in your head.',snoozed:'Resting until you’re ready. Messages return automatically while the app is open.',starred:'The ones worth keeping close.',sent:'Messages sent from this app. Other sent mail is not synced.',drafts:'Your words, saved on this Mac.',archive:'Put aside on this Mac. Your server folders are unchanged.',trash:'Hidden on this Mac. Nothing has been deleted from your mail server.'};$('#subtitle').textContent=subtitles[folder];
 const board=$('#quiet-board');board.hidden=!['quiet','waiting'].includes(folder);
 if(folder==='quiet'){const inbox=folderMail('quiet'),handled=session?.handled.size||0;board.innerHTML=`<div class="quiet-cards">${[['reply','Needs a reply','Give it a little attention'],['later','Read later','When you have a moment'],['done','Done','Let it go']].map(([key,title,note])=>`<button data-quiet="${key}" class="quiet-card ${quietFilter===key?'selected':''}"><span>${title}</span><strong>${inbox.filter(m=>MailLogic.bucket(m)===key).length}</strong><small>${note}</small></button>`).join('')}</div><div class="session-bar"><div><strong>${session?`${handled} of ${session.ids.length} decisions made`:'Small sessions. Clearer head.'}</strong><small>${session?'Choose Reply, Read later, or Done. You can stop any time.':'Try five messages. The initial grouping is a suggestion; you decide.'}</small></div><button id="start-session">${session?'End session':'Start a small session →'}</button></div>`}
 if(folder==='waiting'){const waiting=folderMail('waiting');board.innerHTML=`<div class="radar-filters">${[['all','All reminders'],['due','Due now'],['upcoming','Upcoming'],['replied','Possible replies']].map(([key,title])=>`<button data-radar="${key}" class="${radarFilter===key?'selected':''}">${title} <b>${waiting.filter(m=>key==='all'||MailLogic.radar(m,mails)===key).length}</b></button>`).join('')}</div>`}
 const query=$('#search').value.toLowerCase();let base=folderMail(folder);if(folder==='quiet')base=base.filter(m=>MailLogic.bucket(m)===quietFilter);
 $('#unread-count').textContent=base.filter(m=>m.unread).length;
 let list=base.filter(m=>(filter!=='unread'||m.unread)&&(filter!=='starred'||m.star)&&[m.from,m.subject,m.body,m.email].join(' ').toLowerCase().includes(query));
 if(folder==='waiting'){list=list.filter(m=>radarFilter==='all'||MailLogic.radar(m,mails)===radarFilter)}
 if(folder==='waiting')list.sort((a,b)=>a.followUp.localeCompare(b.followUp));
 $('#mail-count').textContent=`${list.length} ${list.length===1?'message':'messages'}`;
 $('#mail-list').innerHTML=list.length?list.map(m=>{const tracked=m.followUp;const possible=tracked&&MailLogic.possibleReply(m,mails);return `<div class="mail-row ${m.unread?'unread':'read'}"><button class="star ${m.star?'on':''}" data-star="${escape(m.id)}" aria-label="${m.star?'Unstar':'Star'} ${escape(m.subject)}" aria-pressed="${m.star}">${m.star?'★':'☆'}</button><button class="mail-open" data-open="${escape(m.id)}"><span class="sender-avatar">${escape(m.initials||m.from.slice(0,2).toUpperCase())}</span><span class="mail-text"><span class="mail-top"><span class="sender">${escape(m.from)}</span>${tracked?`<span class="tag ${MailLogic.due(m)?'due':''}">${possible?'POSSIBLE REPLY':MailLogic.due(m)?'FOLLOW UP':escape(m.followUp)}</span>`:m.newsletter||m.tag==='NEWSLETTER'?'<span class="tag">READING</span>':''}<time>${escape(dateText(m.time))}</time></span><span class="mail-bottom"><span class="subject">${escape(m.subject||'(No subject)')}</span><span class="snippet">— ${escape(m.snippet||m.body)}</span></span></span><span class="dot"></span></button></div>`}).join(''):`<div class="empty"><img src="mail-icon.png" alt="" width="56" height="56"><h3>${folder==='quiet'?'Room to breathe.':'Nothing here yet.'}</h3><p>${query?'Try a different search.':folder==='waiting'?'Open a conversation and choose Follow up to give it a return date.':'You can check another section, or enjoy the quiet.'}</p></div>`;
 document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('active',b.dataset.filter===filter));
 $('#account-name').textContent=account||'Your little corner';$('#account-state').textContent=account?providerTitle()+' · local sorting':'Demo mailbox';$('#mode-label').textContent=account?providerTitle()+' connected · Sorting & drafts stay on this Mac':'Demo mailbox · No real email is sent';$('#connect-account').textContent=account?'Change account':'Connect mail';$('#sync-mail').hidden=!account;$('#disconnect-account').hidden=!account;$('#sync-mail').disabled=syncing;$('#disconnect-account').disabled=syncing;$('#connect-account').disabled=syncing||!ready;$('#compose').disabled=!ready||!storageHealthy||syncing;$('#undo-change').hidden=!undoAction;
 $('#send-mail').textContent=account?'Send email ↗':'Save to demo sent ↗';$('#compose-note').textContent=account?'Sends through '+providerTitle()+' after confirmation. Drafts stay on this Mac. Attachments are not supported yet.':'Demo mode: messages stay here. No real mail is sent.';
}
$('#folders').onclick=e=>{const b=e.target.closest('[data-folder]');if(!b)return;folder=b.dataset.folder;filter='all';$('#search').value='';render()};$('.filters').onclick=e=>{const b=e.target.closest('[data-filter]');if(b){filter=b.dataset.filter;render()}};$('#search').oninput=render;
$('#quiet-board').onclick=e=>{const r=e.target.closest('[data-radar]');if(r){radarFilter=r.dataset.radar;render();return}const q=e.target.closest('[data-quiet]');if(q){quietFilter=q.dataset.quiet;filter='all';render();return}if(e.target.closest('#start-session')){if(session){session=null;render();toast('Session paused. Your decisions are saved.');return}const ids=folderMail('quiet').filter(m=>MailLogic.bucket(m)!=='done').slice(0,5).map(m=>m.id);if(!ids.length){toast('Nothing asking for your attention. Enjoy the quiet.');return}session={ids,handled:new Set()};render();openMessage(ids[0])}};
function openMessage(id){current=mails.find(m=>String(m.id)===String(id));if(!current)return;if(current.folder==='drafts'){compose(current);return}current.unread=false;current.localRead=true;save();render();$('#message-content').innerHTML=`<h2>${escape(current.subject)}</h2><div class="message-from">${escape(current.from)} &lt;${escape(current.email)}&gt; · ${escape(dateText(current.time))}</div>${current.attachmentCount?`<p class="attachment-note">Attachments available. Open your provider’s mail app to view attachments.</p>`:''}${current.followUp?`<p class="attachment-note">Following up on ${escape(current.followUp)}${MailLogic.possibleReply(current,mails)?' · A possible reply is in your synced inbox. Check before following up.':''}</p>`:''}<div class="message-body">${escape(current.body)}</div>`;$('#wake-message').hidden=!MailLogic.snoozed(current);$('#snooze-message').hidden=current.folder!=='inbox'||MailLogic.snoozed(current);$('#restore-message').hidden=!['archive','trash'].includes(current.folder);$('#show-reply').hidden=!MailLogic.replyMatch(current,mails);$('#mark-unread').hidden=current.folder==='sent';$('#archive').disabled=current.folder==='archive';$('#trash').disabled=current.folder==='trash';if(!$('#reader').open)$('#reader').showModal();window.dispatchEvent(new Event('mail-selected'))}
$('#mail-list').onclick=e=>{const star=e.target.closest('[data-star]');if(star){const m=mails.find(m=>String(m.id)===star.dataset.star);m.star=!m.star;m.localStar=m.star;save();render();return}const b=e.target.closest('[data-open]');if(b)openMessage(b.dataset.open)};
function finishDecision(){if(session&&current&&session.ids.includes(current.id)){session.handled.add(current.id);const next=session.ids.find(id=>!session.handled.has(id));if(next){render();openMessage(next);return}const count=session.ids.length;session=null;$('#reader').close();toast(`${count} little decisions. You’re done for now. Go do something nice.`);window.dispatchEvent(new Event('mail-session-complete'))}else $('#reader').close();render()}
for(const [id,bucket]of [['mark-done','done'],['read-later','later'],['needs-reply','reply']])$('#'+id).onclick=()=>{rememberChange(current);current.quiet=bucket;delete current.snoozedUntil;save();finishDecision()};
for(const target of ['archive','trash'])$('#'+target).onclick=()=>{rememberChange(current);current.folder=target;save();finishDecision();toast(account?'Changed on this Mac. Your server mailbox is unchanged.':'Saved.')};
$('#track-reply').onclick=()=>{$('#reader').close();const d=new Date();d.setDate(d.getDate()+2);$('#followup-date').value=current.followUp||`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;$('#followup-dialog').showModal()};
$('#followup-form').onsubmit=e=>{e.preventDefault();rememberChange(current);current.followUp=$('#followup-date').value;current.waitingSince=Date.now();save();$('#followup-dialog').close();render();toast('Radar will bring this back on your chosen date.')};$('#clear-followup').onclick=()=>{rememberChange(current);delete current.followUp;delete current.waitingSince;save();$('#followup-dialog').close();render()};
function compose(draft){if(!ready||!storageHealthy||syncing)return;clearTimeout(draftSaveTimer);draftId=draft?.id||null;replyTo=draft?.replyTo||null;$('#to').value=draft?.email||'';$('#subject').value=draft?.subject||'';$('#body').value=draft?.body||'';$('#composer').showModal();$('#to').focus()}
$('#compose').onclick=()=>compose();document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$('#'+b.dataset.close).close());
function reply(body){const m=current;if(!m){compose({body:body||''});return}if($('#reader').open)$('#reader').close();compose({email:m.email,subject:m.subject.startsWith('Re: ')?m.subject:'Re: '+m.subject,body:body||'\n\n— Original message —\n'+m.body,replyTo:m.messageID})}
$('#reply').onclick=()=>reply();
function draftRecord(){return {id:draftId||crypto.randomUUID(),from:'You',email:$('#to').value.trim(),initials:'E',subject:$('#subject').value.trim(),body:$('#body').value,unread:false,star:false,folder:'drafts',time:new Date().toISOString(),replyTo}}
function putDraft(close=true){const m=draftRecord();if(!m.email&&!m.subject&&!m.body.trim()){if(draftId){mails=mails.filter(item=>item.id!==draftId);draftId=null;save();render()}if(close)$('#composer').close();return null}mails=mails.filter(x=>x.id!==m.id);mails.unshift(m);draftId=m.id;save();if(close)$('#composer').close();render();return m}
function setSending(value){sending=value;$('#send-mail').disabled=value;$('#close-compose').disabled=value;$('#save-draft').disabled=value;$('#to').disabled=value;$('#subject').disabled=value;$('#body').disabled=value}
$('#compose-form').onsubmit=async e=>{
 e.preventDefault();if(sending)return;clearTimeout(draftSaveTimer);const m=putDraft(false);if(!m)return;setSending(true);
 try{
  if(!await pendingWrites)throw new Error('Your draft could not be saved. Sending has been stopped; your text is still here.');
  const result=account?await bridge('send',{to:m.email,subject:m.subject,body:m.body,replyTo:m.replyTo}):{};
  const sent=mails.find(item=>item.id===m.id)||m;sent.folder='sent';sent.sentAt=Date.now();sent.messageID=result.messageID||'';
  await save();$('#composer').close();current=sent;toast(account?'Accepted by '+providerTitle()+'. Open Sent here to set a follow-up.':'Saved to demo sent. No real email was sent.');render();
 }catch(error){toast(error.message)}finally{setSending(false)}
};
$('#save-draft').onclick=()=>{putDraft();toast('Draft saved on this Mac.')};$('#close-compose').onclick=()=>putDraft();$('#composer').addEventListener('cancel',e=>{e.preventDefault();if(!sending)putDraft()});
async function applySync(result){provider=result.provider||'icloud';const next=result.email.toLowerCase();if(account!==next){$('#reader').close();account=next;load();await loadNativeCache()}const incoming=result.messages.map(m=>({...m,remote:true,folder:'inbox',initials:m.from.slice(0,2).toUpperCase(),snippet:m.body.slice(0,160)}));mails=MailLogic.merge(mails,incoming);if(current)current=mails.find(m=>m.id===current.id)||null;await save();render();showStatus(`Updated ${new Date().toLocaleTimeString(undefined,{hour:'2-digit',minute:'2-digit'})} · Latest ${incoming.length} inbox messages. Mail is displayed as text; attachments stay with your provider.`)}
async function sync(action){if(syncing||!ready)return;if(!await pendingWrites){showStatus('Save your local changes successfully before switching or refreshing.',true);return}if($('#composer').open){toast('Save or close your draft before switching accounts.');return}syncing=true;render();showStatus(action==='connect'?'Choose your provider in the account window.':'Checking '+providerTitle()+'…');try{await applySync(await bridge(action))}catch(error){showStatus(error.message,true)}finally{syncing=false;render()}}
$('#connect-account').onclick=()=>sync('connect');$('#sync-mail').onclick=()=>sync('sync');$('#disconnect-account').onclick=async()=>{if(syncing||sending)return;if($('#composer').open){toast('Save your draft first.');return}if(!await pendingWrites){toast('Save your local changes before disconnecting.');return}syncing=true;render();try{await bridge('disconnect');$('#reader').close();account='';provider='icloud';load();await loadNativeCache();folder='quiet';render();showStatus('Disconnected. Your server mail is unchanged.')}catch(error){toast(error.message)}finally{syncing=false;render()}};
document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)&&!document.querySelector('dialog[open]')){e.preventDefault();$('#search').focus()}});
load();render();
if(native)(async()=>{try{const result=await bridge('status');if(result.connected){account=result.email;provider=result.provider||'icloud';load()}await loadNativeCache();ready=true;render();if(account)sync('sync')}catch(error){ready=true;showStatus(error.message,true);render()}})();
setInterval(()=>{if(['quiet','waiting','snoozed'].includes(folder))render()},30000);
window.mailForBuddy=()=>current?{id:current.id,subject:current.subject,email:current.email,body:current.body}:null;
window.useBuddyDraft=(text,sourceID)=>{if($('#composer').open){toast('Save your current draft before using Buddy’s answer.');return}if(sourceID)reply(text);else compose({body:text})};

// Keep unfinished writing safe when closing the app or switching away.
let draftSaveTimer;for(const field of ['to','subject','body'])$('#'+field).addEventListener('input',()=>{clearTimeout(draftSaveTimer);draftSaveTimer=setTimeout(()=>{if($('#composer').open&&!sending)putDraft(false)},500)});
window.flushDraft=async()=>{clearTimeout(draftSaveTimer);if($('#composer').open&&!sending)putDraft(false);return !sending&&await pendingWrites};
window.addEventListener('pagehide',()=>window.flushDraft());

$('#undo-change').onclick=undoChange;
$('#snooze-message').onclick=()=>{rememberChange(current);current.snoozedUntil=MailLogic.tomorrow();save();finishDecision();toast('Snoozed until tomorrow at 9. Find it in Snoozed any time.')};
$('#wake-message').onclick=()=>{rememberChange(current);delete current.snoozedUntil;save();$('#reader').close();render();toast('Back in your Quiet Inbox.')};
$('#restore-message').onclick=()=>{rememberChange(current);current.folder='inbox';save();$('#reader').close();render();toast('Returned to your inbox on this Mac.')};
$('#mark-unread').onclick=()=>{rememberChange(current);current.unread=true;current.localRead=false;save();$('#reader').close();render()};
$('#show-reply').onclick=()=>{const match=MailLogic.replyMatch(current,mails);if(match)openMessage(match.id)};

$('#start-connect').onclick=()=>sync('connect');

// Familiar shortcuts avoid intercepting typing or open dialogs.
document.addEventListener('keydown',e=>{
 if(!(e.metaKey||e.ctrlKey)||document.querySelector('dialog[open]'))return;
 if(e.key.toLowerCase()==='r'&&account){e.preventDefault();sync('sync')}
 if(e.key.toLowerCase()==='f'){e.preventDefault();$('#search').focus()}
 if(e.key.toLowerCase()==='n'){e.preventDefault();compose()}
});

$('#toolbar-buddy').onclick=()=>$('#buddy-toggle').click();
